const l=[{id:"meaning-frankl",title:"M17 · Viktor Frankl Institute of America · Meaning from a logotherapy perspective",url:"https://viktorfranklamerica.com/meaning-from-a-logotherapy-perspective/",type:"guidance",finding:"Frankl described meaning through creating or doing, experiencing or loving, and an optional stance toward unavoidable suffering.",limitation:"A philosophical and clinical account, not a trial. Suffering is not required, and this reflection does not establish treatment effects."},{id:"meaning-frankl-history",title:"M18 · Viktor Frankl Institute Vienna · Biography",url:"https://www.viktorfrankl.org/biography.html",type:"guidance",finding:"Frankl developed logotherapy before his Nazi imprisonment. The institutional biography documents his life and work.",limitation:"Historical experience does not establish the efficacy of a psychological intervention or require you to find meaning in suffering."},{id:"meaning-act-values",title:"M19 · Association for Contextual Behavioral Science · Six core processes of ACT",url:"https://contextualscience.org/six_core_processes_act",type:"guidance",finding:"In ACT, values are ongoing qualities of action; committed action connects them to concrete goals.",limitation:"Professional model guidance, not an experiment. ODA’s compass and short actions are adaptations with no validated score or isolated effect."},{id:"meaning-act-trials",title:"M04 · A-Tjak et al. · 2015 · ACT meta-analysis",url:"https://doi.org/10.1159/000365764",type:"research",finding:"39 randomized trials involving 1,821 people tested full ACT packages for clinically relevant mental or physical problems.",limitation:"Clinical package evidence does not isolate values worksheets, validate this course, or establish superiority to established CBT."},{id:"meaning-sdt",title:"M05 · Ryan & Deci · 2000 · Self-determination theory",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"The theory distinguishes personally endorsed motivation from pressure; some externally introduced responsibilities can become personally endorsed.",limitation:"A theory article, not a motive test. Guilt, pleasure, bodily energy, and whether others notice do not diagnose a value’s authenticity."},{id:"meaning-sdt-interventions",title:"M06 · Ntoumanis et al. · 2021 · Health motivation interventions",url:"https://eprints.whiterose.ac.uk/id/eprint/155741/",type:"research",finding:"73 health intervention studies with 30,088 participants found average improvements in autonomous motivation and health behavior, with heterogeneous effects.",limitation:"58 randomized and 15 quasi-experimental studies used varied supported programs. A brief values worksheet is not the studied intervention."},{id:"meaning-support",title:"M20 · National Institute of Mental Health · Depression",url:"https://www.nimh.nih.gov/health/publications/depression",type:"guidance",finding:"Persistent low mood, hopelessness, loss of interest, or impaired functioning deserves professional evaluation and support. US crisis support is available through 988.",limitation:"Loss of meaning alone does not diagnose depression. ODA is educational support and cannot treat depression or manage an acute crisis."},{id:"meaning-carrillo",title:"M09 · Carrillo et al. · 2019 · Best Possible Self meta-analysis",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"29 studies with 2,909 participants supported average improvements in well-being, positive feelings, and optimism. Reductions in negative feelings and depression were not established.",limitation:"Both symptom confidence intervals crossed zero; only three studies measured depression. Mostly short-term, varied protocols. Neither meaning nor future achievement was established."},{id:"meaning-best-possible-self",title:"M10 · King · 2001 · Writing about life goals",url:"https://doi.org/10.1177/0146167201277003",type:"research",finding:"81 undergraduates were randomized across four writing conditions. The future-writing task used 20 minutes on each of four consecutive days.",limitation:"The original task did not test this short, values-linked ODA adaptation. It did not establish greater meaning, illness prevention, or actual future attainment."},{id:"meaning-planning",title:"M11 · Gollwitzer & Sheeran · 2006 · Implementation intentions",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 independent tests with 8,461 participants supported average goal-attainment benefits from plans linking a specific situation to an intended response.",limitation:"The pool included experimental and correlational tests. Contexts varied; planning is not action, and the review did not establish increased meaning or this combined ODA flow."},{id:"meaning-mental-contrasting",title:"M13 · Wang, Wang & Gai · 2021 · Mental contrasting and planning",url:"https://www.frontiersin.org/articles/10.3389/fpsyg.2021.565202/pdf",type:"research",finding:"24 independent studies from 21 articles, with 15,907 participants, found a modest average goal-attainment effect, g = 0.336 [0.229, 0.443].",limitation:"Publication bias and varied formats limit precision. The combined values, future-scene, and action adaptation was not tested; structural barriers are not personal failures."},{id:"meaning-monitoring",title:"M14 · Harkin et al. · 2016 · Progress monitoring",url:"https://eprints.whiterose.ac.uk/id/eprint/87431/1/bul%20harkin%20raw%20final.pdf",type:"research",finding:"138 randomized studies found average goal-attainment benefits from increased monitoring, d = 0.40 [0.32, 0.48].",limitation:"Small-study asymmetry was detected; a sensitivity analysis estimated d = 0.19. Heterogeneous goals and methods do not validate ODA’s next-day timing, meaning effects, or compulsory public tracking."},{id:"meaning-habits",title:"M15 · Lally et al. · 2010 · Habit formation",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"An 84-day observational study followed 96 participants. Modeled automaticity grew at varying rates; one missed opportunity had little measured impact.",limitation:"The often-quoted 66-day median and 18–254-day range are modeled estimates, with longer values extrapolated. They are not deadlines or evidence about repeated gaps or values becoming automatic."}],r=[{schemaVersion:2,revision:2,id:"meaning-1",courseId:"meaning",locale:"en",title:"Busy all week. What actually mattered?",goal:"Give one chosen contribution or relationship a useful action today.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Another week of work, chores, and scrolling? Give one thing you care about an actual turn.",reason:{id:"meaning-1-reason-attention-cost",label:"What optional activity would you postpone to give this direction two minutes?",kind:"text",maxLength:160,optional:!0,suggestions:["Postpone optional scrolling","Move a nonurgent chore","Give connection a small opening"]},why:{id:"meaning-1-why",label:"What matters enough to receive your attention this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["You do not need one grand purpose before doing something you care about. Frankl’s philosophy describes several possible routes: creating or doing, experiencing or loving, and a stance toward unavoidable hardship. These are prompts, not a test or a proven treatment. You can leave hardship out.","Choose one contribution or relationship for this course’s continuing experiment. Give it a small action, a real opening, and a record afterward. Asking a question and listening is an action. Listing who matters is preparation. Your mood can stay unchanged; notice what you actually do."],example:{title:"Tomás’s dinner question",text:"At Tuesday dinner, Tomás realizes he has barely heard his daughter all week. He puts his phone away, asks about her science project, and listens to her answer. She gives him two short sentences before leaving. He records that he asked and stayed attentive. The conversation was brief, but it happened."}},move:{invitation:"Give your chosen relationship or contribution one useful action.",instructions:["Choose one direction to keep through this course.","Do a small act, then record what happened."],prompts:[],suggestions:{action:["Ask and listen without checking my phone","Finish one useful project sentence","Offer one specific piece of help"],minimum:["Ask one question and listen","Write one usable sentence","Make one specific offer"],cue:["When we sit down after dinner","When I open my project","At my next safe check-in"],place:["At the kitchen table","At my usual work surface","In a safe message thread"],minutes:[2,5],fallback:["Use a safe voice or text message","Choose another available opening","Ask for practical support"],observation:["What I asked and heard","The useful sentence I produced","Whether my offer was made"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask and listen without checking my phone",minimum:"Ask one question and listen",minutes:2,cueHint:"When we sit down after dinner",placeHint:"At the kitchen table",obstacleHint:"The person is unavailable or my attention wanders.",fallbackHint:"Use a safe voice or text message",observationHint:"What I asked and heard"},stopRule:"Choose a safe, wanted interaction. Helping must fit your resources and boundaries.",accessibleAlternative:"Use your usual communication method, an assisted contribution, or a private creative act."},result:{question:"Did you do your chosen act?",observationPrompt:"What did you contribute, ask, or hear?"},judgment:{primary:{id:"meaning-1-dinner-opening-decision",scenario:"Tomás chose to hear about his daughter’s project tonight. She has five minutes before leaving. The dinner dishes can wait; he also wants to prepare a useful question.",question:"Which use of this opening serves his chosen direction?",options:[{id:"listen-now",text:"Ask about the project and listen now, then record what actually happened.",feedback:"This uses the opening for the attentive conversation he chose. The answer may be short or distracted. Dishes and more preparation can wait without making connection the right priority for everyone."},{id:"meaning-1-share-chore",text:"Wash dishes together during the five minutes and ask about the project while clearing the table.",feedback:"A shared chore can support connection. Here Tomás chose focused listening, and the dishes can wait. Protect a brief conversation rather than splitting his attention unless they both prefer the shared task."},{id:"meaning-1-prepare-question",text:"Use the five minutes to prepare a thoughtful project question, then send it after she leaves.",feedback:"Preparing a question can make a later conversation easier. Here she is available and he already knows the topic. Ask now; record no occasion if she chooses not to talk."}],bestOptionId:"listen-now"}},carry:{takeaway:"Give what matters an actual turn, then bring back the facts.",followUp:{questionId:"meaning-1-return",question:"What happened when your chosen opening arrived?",observationPrompt:"What act happened, and was the opening available?",adjustmentPrompt:"What would you move or change for the next opening?"}},goDeeper:{sections:[{heading:"A philosophy with more than one route",paragraphs:["Frankl’s three routes come from a philosophical and clinical account, not a checklist everyone must complete. Creating may mean useful work or a deed. Experiencing may mean noticing beauty or attending to a relationship. An attitude toward unavoidable suffering is another possibility, never a requirement. You can choose contribution or connection without describing pain. Frankl’s Institute of America account describes these routes [M17].","The Vienna institute’s biography documents that Frankl was developing logotherapy before his Nazi imprisonment [M18]. His later experience is part of his history, not evidence that a brief lesson treats distress. This course borrows questions from the philosophy and leaves answers with you. If no grand answer appears, you can still choose a modest action. An attentive question, a useful paragraph, or a bounded offer of help gives your selected direction something observable."]},{heading:"From noticing to a real opportunity",paragraphs:["A meaningful-looking plan and a completed action are different records. Planning research supports specifying an opportunity and a response: when a recognizable situation occurs, do the behavior you intend. Gollwitzer and Sheeran pooled 94 independent tests involving 8,461 participants [M11]. Goal attainment improved on average, but tests included different populations, goals, and designs. The result does not establish that planning raises meaning or that this course’s combined philosophy and action flow works.","ODA’s adaptation lets you choose one direction, an act, and a feasible minimum. Keep the first act relevant: listening to one answer serves connection; merely opening a contacts list is preparation. Record an unavailable opening as no occasion, and a future appointment as planned. You do not need to prove that the conversation changed your life. Its practical value is information for your next choice, including whether another setting, support, or a different direction would suit you better."]}],sourceIds:["meaning-frankl","meaning-frankl-history","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-2",courseId:"meaning",locale:"en",title:"What matters gets your leftover minutes?",goal:"Protect a small action for your existing direction and name what must wait.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"You say this matters. Does it get time, or whatever is left after everything else?",reason:{id:"meaning-2-reason",label:"What will you move so this direction gets time?",kind:"text",maxLength:160,optional:!0,suggestions:["Move optional scrolling","Keep a smaller commitment","Make room for careful work"]},why:{id:"meaning-2-why",label:"What will you move so this direction gets time?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A goal is something you can finish, such as visiting someone Sunday. A value is an ongoing way you want to act, such as being attentive. That distinction comes from a therapy model, not a rule that goals are less important. Missing one destination does not settle which direction you want.","Reuse your experiment’s direction and action. Look at the next available slot. Two worthwhile things may compete for it. Choose a useful minimum and say what will wait. This is a real trade-off, not proof that the other value disappeared. Do the act before judging the choice."],example:{title:"Tomás makes room",text:"On Wednesday, Tomás has ten minutes before a household task. He wants another conversation and also wants to read. He gives two minutes to his daughter’s project, then starts the task. Reading waits until Thursday. His daughter seems distracted, and he records that too. He chose a bounded act rather than fitting everything in."}},move:{invitation:"Keep your direction. Give its next act a feasible slot.",instructions:["Name one competing use of this time.","Choose a useful minimum and do it."],prompts:[],suggestions:{action:["Ask and listen in my protected slot","Write a useful project sentence","Complete one bounded care task"],minimum:["Listen to one answer","Produce one usable sentence","Complete one small agreed task"],cue:["When we sit down after dinner","At my protected project slot","After an existing care routine"],place:["At the kitchen table","At my usual work surface","Where the task is needed"],minutes:[2,5],fallback:["Use a shorter available conversation","Reduce the useful task size","Ask to share the responsibility"],observation:["The act and what waited","Time I actually used","Whether the smaller version served my direction"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask and listen in my protected slot",minimum:"Listen to one answer",minutes:2,cueHint:"When we sit down after dinner",placeHint:"At the kitchen table",obstacleHint:"Two worthwhile commitments compete for the same slot.",fallbackHint:"Use a shorter available conversation",observationHint:"The act and what waited"},stopRule:"Do not displace urgent care or needed recovery. Change the slot or size instead.",accessibleAlternative:"Use assisted communication, a seated task, or support to protect the same direction."},result:{question:"Did you do the protected minimum?",observationPrompt:"What did you do, and what did you leave for later?"},judgment:{primary:{id:"meaning-2-chosen-commitment-decision",scenario:"Tomás promised an attentive conversation before his daughter’s trip. Tonight’s ten minutes are their last opening. He also values finishing a nonurgent reading chapter; a longer call can wait until next week.",question:"Which choice keeps his commitment within this slot?",options:[{id:"reading-later",text:"Listen briefly now and choose another reading slot, accepting that this time is limited.",feedback:"This keeps the conversation he chose while tonight’s opening exists. Reading still matters and can have another slot. The case turns on his commitment and timing, not which value outranks another."},{id:"full-both",text:"Try to finish the chapter while listening, so neither important commitment has to wait.",feedback:"Combining tasks can protect reading time, but it divides the attention he promised. Use a short listening minimum now and move reading, rather than claiming that both full commitments fit."},{id:"meaning-2-next-week-call",text:"Read tonight and schedule a longer conversation next week, giving both commitments their own protected time.",feedback:"Separate slots can be sensible, and a longer call may be worthwhile. It still misses the before-trip conversation he chose. Keep the small commitment now; schedule a longer follow-up separately."}],bestOptionId:"reading-later"}},carry:{takeaway:"A direction can survive a missed goal. Give it a feasible action now.",followUp:{questionId:"meaning-2-return",question:"Did your protected slot serve the direction you chose?",observationPrompt:"Did the minimum serve your direction, and what had to wait?",adjustmentPrompt:"Keep the trade-off or change the slot or size?"}},goDeeper:{sections:[{heading:"Direction and destination are different tools",paragraphs:["The Association for Contextual Behavioral Science describes values as chosen qualities of ongoing action and committed action as linking those qualities to concrete goals [M19]. Being attentive is a direction. Listening to one answer tonight is a finite act. They work together. You can finish the act without finishing attentiveness, and you can revise a goal while keeping the direction. These are distinctions within the ACT model, not experimentally discovered universal categories.","ODA’s compass is a teaching adaptation: choose a life area, name the quality you want to express, consider your circumstances, and choose a feasible act. It has no validated score cutoff. You do not need to rate every area or repair the largest numerical gap. A person with care duties, limited energy, or an inflexible shift may choose sustainability first. Use your actual week to decide what gets a turn, rather than treating the compass as a verdict on your life."]},{heading:"A brief action is not a therapy package",paragraphs:["A-Tjak and colleagues reviewed 39 randomized trials with 1,821 participants facing clinically relevant mental or physical problems [M04]. Those studies tested full acceptance and commitment therapy packages, with varying conditions and comparisons. They did not isolate a values compass, establish the effect of this single worksheet, or show that ODA delivers therapy. A useful framework can guide a choice without inheriting the entire package’s clinical evidence.","The scheduling component has separate support from specific cue-response planning research [M11]. A cue such as sitting down after dinner is more recognizable than “sometime this week.” That evidence concerns goal attainment, not feeling fulfilled. Keep your minimum meaningful and its cost visible. If you postpone a nonurgent task, name the next slot rather than pretending the trade-off vanished. If the slot threatens essential care or recovery, shrink the act, obtain help, or choose a different opening."]}],sourceIds:["meaning-act-values","meaning-act-trials","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-3",courseId:"meaning",locale:"en",title:"Your choice can still feel difficult",goal:"Act on one reason you endorse while respecting responsibilities and constraints.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Still feel guilty about a choice you care about? That feeling does not decide whether the choice is yours.",reason:{id:"meaning-3-reason",label:"Which reason do you endorse, and what must you protect?",kind:"text",maxLength:160,optional:!0,suggestions:["Care for people I love","Keep financial responsibilities","Choose one elective commitment"]},why:{id:"meaning-3-why",label:"Which reason do you endorse, and what must you protect?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A responsibility learned from family can become one you personally endorse. Motivation research distinguishes acting from endorsed reasons and acting under pressure, but it does not offer an instant authenticity test. Feeling guilty, tired, or pleased tells you something about your experience. It does not settle which value belongs to you.","Look at the same direction you have been testing. Name a reason you still support and a constraint you need to respect. Keep essential obligations. Change one low-cost elective choice, then do the useful act. Mixed motives are allowed. You do not need perfect certainty first."],example:{title:"Tomás keeps an endorsed reason",text:"On Thursday at the kitchen table, Tomás feels guilty about declining an optional work chat. He still endorses being present with his daughter and keeps his required shift. During their two minutes he asks about her model and listens. He records the conversation and the unease. His reason remained chosen even though the guilt stayed."}},move:{invitation:"Test one endorsed reason through your existing small act.",instructions:["Keep necessary obligations and name one elective trade-off.","Do the act without demanding a clear feeling."],prompts:[],suggestions:{action:["Ask and listen for a reason I endorse","Make one elective project contribution","Decline one optional competing invitation"],minimum:["Listen to one answer","Produce one useful sentence","State one clear availability limit"],cue:["When we sit down after dinner","At my elective project slot","When the optional invitation arrives"],place:["At the kitchen table","At my usual work surface","In a safe message thread"],minutes:[2,5],fallback:["Keep obligations and shrink this act","Choose a lower-cost elective choice","Ask for support with the constraint"],observation:["What I chose despite mixed feelings","The reason I still endorse","The obligation I protected"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask and listen for a reason I endorse",minimum:"Listen to one answer",minutes:2,cueHint:"When we sit down after dinner",placeHint:"At the kitchen table",obstacleHint:"I feel pressure, and some responsibilities cannot be dropped.",fallbackHint:"Keep obligations and shrink this act",observationHint:"What I chose despite mixed feelings"},stopRule:"Avoid irreversible changes. Protect essential income, care, safety, and needed support.",accessibleAlternative:"Use a private or assisted choice, a safe written limit, or practical support."},result:{question:"Did you carry out your chosen act?",observationPrompt:"What did you choose, and which responsibility did you protect?"},judgment:{primary:{id:"meaning-3-elective-cost-decision",scenario:"Tomás values income and tonight’s family conversation. The networking chat is repeated tomorrow with the same contacts; skipping tonight affects no paid shift. Guilt still pushes him to attend every event.",question:"Which choice tests his reason at a manageable cost?",options:[{id:"meaning-3-attend-and-reschedule",text:"Attend tonight’s chat and schedule a family conversation after his next shift, preserving both commitments.",feedback:"Rescheduling can protect two worthwhile commitments. Here the same contacts are available tomorrow without income loss. Moving tonight’s chosen conversation responds to pressure while passing up an available lower-cost alternative."},{id:"endorsed-choice",text:"Keep the required shift, decline tonight’s optional event, and use the conversation slot he values.",feedback:"This tests the reason he endorses while protecting income and retaining tomorrow’s networking opportunity. Guilt may remain. If the professional cost were different, another trade-off could be appropriate."},{id:"meaning-3-split-evening",text:"Join the chat briefly, then shorten the family conversation so he stays visible at both.",feedback:"A split can work when both openings are scarce. Here networking repeats tomorrow. Dividing tonight protects visibility at the cost of the attention he chose; use the separate available opening instead."}],bestOptionId:"endorsed-choice"}},carry:{takeaway:"Endorse a reason, respect its costs, and test it in a small choice.",followUp:{questionId:"meaning-3-return",question:"Do you still endorse the reason after making the choice?",observationPrompt:"What reason do you endorse now, including uncertainty or change?",adjustmentPrompt:"Keep the reason, revise it, or get support with its cost?"}},goDeeper:{sections:[{heading:"Inherited does not mean inauthentic",paragraphs:["Ryan and Deci’s self-determination theory describes how externally introduced motives can become personally endorsed [M05]. A family responsibility can be difficult, relational, and yours. Enjoyment is one possible reason to act; caring about someone’s security is another. This does not make every pressured commitment healthy. It means origin, discomfort, or recognition alone cannot decide authenticity. Ask which reasons you currently endorse and which pressures constrain the choice.","The nobody-watching question is an optional reflection prompt, not a validated test. Guilt does not prove a borrowed value, and bodily energy does not prove a true one. Asking why can help you reflect. It cannot certify that one motive is your true motive. You may find mixed reasons and still make a deliberate choice. Protect necessary income and care, acknowledge cultural commitments, and test a reversible elective action. No change in career, relationship, or family obligation is required to finish this lesson."]},{heading:"Support changes motivation; a worksheet has limits",paragraphs:["Ntoumanis and colleagues pooled 73 health-domain intervention studies involving 30,088 participants [M06]. The programs supported average improvements in autonomous motivation and health behavior, with substantial variation. The pool contained 58 randomized and 15 quasi-experimental studies. This evidence concerns supported health interventions. It does not show that three questions reveal a hidden true motive, that external motives are always harmful, or that a short ODA exercise reproduces the programs.","The ACT model also connects chosen ongoing qualities with concrete action [M19]. Here that connection is an ODA adaptation, not a tested combined treatment. Use the next attempt to learn something specific: did this choice fit your responsibilities, and do you still endorse its reason? An uneasy feeling can remain in the record. If pressure involves coercion or danger, protection and support take priority over experimenting with compliance. You can change the direction, keep it privately, or pause without explaining yourself."]}],sourceIds:["meaning-sdt","meaning-sdt-interventions","meaning-act-values"]}},{schemaVersion:2,revision:2,id:"meaning-4",courseId:"meaning",locale:"en",title:"A hard chapter owes no silver lining",goal:"Protect your chosen direction with one practical request, boundary, or humane act.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Trying to make this pain meaningful? Start with what can be helped, and let the meaning question wait.",reason:{id:"meaning-4-reason",label:"What practical change would make this direction sustainable?",kind:"text",maxLength:160,optional:!0,suggestions:["Share a care task","Protect needed rest","Ask for qualified support"]},why:{id:"meaning-4-why",label:"What practical change would make this direction sustainable?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["An event may be unchangeable while present arrangements can still change. An illness deserves care and assessment, not automatic placement in a “nothing can be done” column. Frankl’s idea of a stance toward unavoidable suffering is a philosophical possibility. It is not a duty to find a gift in pain.","Return to your experiment. If strain is making its action unsustainable, change the support around it. Ask for one practical task, set a safe boundary, or protect needed rest. These can serve the same direction. Record the actual request or change. Feeling meaningful is not the requirement."],example:{title:"Tomás shares the care load",text:"On Friday, Tomás feels drained after arranging his father’s visits. He wants to keep caring without losing every evening. At the kitchen table he sends his brother a request to handle Saturday’s transport. His brother has not replied by bedtime. Tomás records the request. The sadness remains, and he does not turn it into a lesson."}},move:{invitation:"Keep the direction. Change one burden that can be helped.",instructions:["Check for a practical change before an attitude exercise.","Make one specific request or safe protective act."],prompts:[],suggestions:{action:["Ask for help with one care task","Set one safe availability boundary","Request qualified support"],minimum:["Send one specific help request","State one clear limit","Make one support contact"],cue:["After dinner before planning visits","When the next request arrives","At my chosen support opening"],place:["At the kitchen table","In a safe message thread","In my accessible private space"],minutes:[2,5],fallback:["Ask another suitable support person","Keep the boundary private and get help","Choose an accessible support route"],observation:["The request and any response","The practical arrangement I changed","Whether I made the support contact"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask for help with one care task",minimum:"Send one specific help request",minutes:2,cueHint:"After dinner before planning visits",placeHint:"At the kitchen table",obstacleHint:"The first person cannot help, or contact is unsafe.",fallbackHint:"Ask another suitable support person",observationHint:"The request and any response"},stopRule:"For US crisis support, call/text 988; elsewhere use local crisis support. In immediate danger, use local emergency services.",accessibleAlternative:"Use an assisted request or rest. Seek professional support sooner if hopelessness persists or daily functioning suffers."},result:{question:"Did you make your chosen practical move?",observationPrompt:"What did you request or change, including no response?"},judgment:{primary:{id:"meaning-4-transport-constraint-decision",scenario:"Saturday’s medical transport leaves Tomás exhausted. His brother offered to drive if confirmed tonight. Visits can be shorter, but transport is required. Free community transport has no Saturday space.",question:"Which arrangement addresses the current burden?",options:[{id:"meaning-4-shorten-visits",text:"Shorten Saturday’s visit and keep driving, so he reduces the demand without coordinating another person.",feedback:"Shorter visits can protect energy and may still help. They do not change the required driving that is draining him. Confirm the available transport offer, then choose a sustainable visit length."},{id:"meaning-4-community-route",text:"Ask community transport about a cancellation place and wait for that answer before confirming his brother.",feedback:"Community transport could be a useful future route. Saturday has no confirmed space, while his brother’s offer needs an answer tonight. Secure the available help rather than making it depend on a cancellation."},{id:"share-task",text:"Ask his brother to handle transport, then choose a visit length he can sustain.",feedback:"This uses the available offer for the burden that can change, while keeping medical transport covered. The request can be completed before agreement arrives. Record an unanswered request as such."}],bestOptionId:"share-task"}},carry:{takeaway:"Change the help and the arrangement before demanding a better attitude.",followUp:{questionId:"meaning-4-return",question:"What help or practical change followed your request?",observationPrompt:"What response or arrangement changed, including no reply?",adjustmentPrompt:"What help, boundary, or rest fits the remaining burden?"}},goDeeper:{sections:[{heading:"Past facts and present possibilities",paragraphs:["Frankl’s account includes a possible stance toward suffering that truly cannot be avoided [M17]. This is philosophical guidance, not evidence that attitude cures illness or makes trauma useful. A death or past event cannot be reversed. Current symptoms, treatment options, social support, and daily arrangements may still be changeable. Do not place a diagnosis, another person’s harm, or lack of assistance in an unchangeable column without considering help.","The ACT model offers chosen qualities of action during difficult feelings [M19]. It does not require making those feelings disappear or remaining in preventable danger. Your experiment can retain care as its direction while changing from another visit to a request for shared transport. Rest, a boundary, or getting information may be the appropriate act. These are choices to assess in context, not proof of a noble attitude. You may leave the meaning question unanswered, and you never owe an account of suffering to ODA."]},{heading:"Support does not wait for purpose",paragraphs:["The National Institute of Mental Health describes depression symptoms and professional evaluation and treatment options [M20]. Persistent hopelessness, low mood, loss of interest, or difficulty functioning deserves support. Loss of meaning alone is not a diagnosis, and a course cannot make that assessment. You can seek help before symptoms reach any duration threshold. Do not wait to complete the course or produce a values answer before contacting a doctor or mental health professional.","In the United States, call or text 988 for suicide or emotional crisis support. For immediate danger use emergency services. Elsewhere use local crisis or emergency resources. The appropriate next move in a crisis is human help, not another reflection exercise. Outside crisis, your request can stay specific and modest: a practical care task, time to recover, or an appointment. No reply is still a factual observation. If the first route is unavailable, seek another suitable route rather than interpreting that obstacle as a failure of meaning."]}],sourceIds:["meaning-frankl","meaning-act-values","meaning-support"]}},{schemaVersion:2,revision:2,id:"meaning-5",courseId:"meaning",locale:"en",title:"Your imagined future needs one real piece",goal:"Use a modest future scene to choose a concrete act for your existing direction.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Your future looks clear in your head. What piece of it will exist in your actual week?",reason:{id:"meaning-5-reason",label:"What must change this week for that future to fit?",kind:"text",maxLength:160,optional:!0,suggestions:["Show up for connection","Make one useful artifact","Respect my budget and energy"]},why:{id:"meaning-5-why",label:"What must change this week for that future to fit?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Future writing has clearer research support for optimism and positive feelings than for reducing depression or negative feelings. It does not establish that the imagined life happens. A short scene can be preparation for your experiment, not evidence that you have acted.","Picture an ordinary near-future day if that helps. Keep your existing direction and choose its next visible piece: a real conversation, useful sentence, or specific request. Face the obstacle and your resources. Then do the piece. Skip future imagery if it is unhelpful. You can choose the action directly instead."],example:{title:"Tomás’s ordinary Tuesday",text:"At Saturday breakfast, Tomás pictures a Tuesday when care duties are shared and he helps at home. The scene is preparation. He turns one part into action: writing a clear label for his daughter’s school model. He finishes the label at the kitchen table; the rest of the model still needs work."}},move:{invitation:"Turn one piece of your future into today’s existing act.",instructions:["Use a short scene if useful. This is preparation.","Name a real obstacle, then do one relevant piece."],prompts:[],suggestions:{action:["Write one useful project sentence","Make one useful project sketch","Send one relevant feedback request"],minimum:["Produce one usable sentence","Draw one usable outline","Send one specific feedback question"],cue:["When I open my project","When the project needs an outline","At my protected work slot"],place:["At my usual work surface","At the kitchen table","In a safe message thread"],minutes:[2,5],fallback:["Choose a smaller relevant contribution","Use a text description instead","Ask for help with access"],observation:["The piece I actually contributed","What the obstacle changed","The request and any response"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one useful project sentence",minimum:"Produce one usable sentence",minutes:2,cueHint:"When I open my project",placeHint:"At my usual work surface",obstacleHint:"The imagined version exceeds my available resources.",fallbackHint:"Choose a smaller relevant contribution",observationHint:"The piece I actually contributed"},stopRule:"Keep the future modest and safe. Skip imagery if distress grows; avoid costly commitments.",accessibleAlternative:"Choose the act directly, use words instead of imagery, or make an assisted contribution."},result:{question:"Did you produce your chosen piece?",observationPrompt:"What actually existed or happened after your attempt?"},judgment:{primary:{id:"meaning-5-feedback-opening-decision",scenario:"A designer has one finished sample and a colleague’s feedback opening tonight. The intended future is shared work; stronger equipment can be borrowed next week, but this sample needs none.",question:"Which move tests that direction within current resources?",options:[{id:"meaning-5-prepare-presentation",text:"Spend tonight improving the sample’s presentation, then ask for feedback at the colleague’s next opening.",feedback:"Better presentation can clarify a sample. This one is finished, and the feedback opening is tonight. Send a specific question now; use the answer to decide whether presentation needs work."},{id:"share-sample",text:"Protect the budget and send the existing sample with one specific feedback question.",feedback:"This tests a relevant behavior within current resources. Future writing and goal attainment are different outcomes. An imperfect reply still gives information for the next attempt."},{id:"meaning-5-borrow-equipment",text:"Wait for next week’s borrowed equipment, then make a stronger sample before asking for feedback.",feedback:"Borrowing can protect the budget when equipment is necessary. This sample needs none, and the colleague is available now. Test shared work with the existing sample before expanding its requirements."}],bestOptionId:"share-sample"}},carry:{takeaway:"A future scene is preparation. Give its direction one real piece today.",followUp:{questionId:"meaning-5-return",question:"Did your act connect the future scene to this week?",observationPrompt:"What piece existed, and how did it serve your direction?",adjustmentPrompt:"What resource or obstacle should the next piece address?"}},goDeeper:{sections:[{heading:"What future writing has actually shown",paragraphs:["Carrillo and colleagues combined 29 studies with 2,909 participants [M09]. The pooled results supported average improvements in well-being, optimism, and positive feelings. Reductions in negative feelings and depressive symptoms were not established. Their confidence intervals included zero, and only three studies assessed depression. A positive-looking average number cannot settle an uncertain estimate. The studies mostly measured short-term outcomes and used varied writing protocols; they did not establish greater meaning or actual future achievement.","King’s original future-writing task used 20 minutes on each of four consecutive days, with 81 undergraduates randomized across four writing conditions [M10]. The short, near-future, values-linked scene here changes the dose and purpose. It is an ODA adaptation, not that original procedure. Optional longer writing needs its own time. You do not have to produce an ideal five-year life or compare yourself with it. An ordinary possibility can be enough to select a practical next act."]},{heading:"Give the future a present obstacle",paragraphs:["Mental contrasting with implementation intentions joins a feasible wish, its desired outcome, a present obstacle, and an if–then response. Wang and colleagues reviewed 24 independent studies from 21 articles, with 15,907 participants [M13]. Goal attainment showed a modest average effect, g = 0.336, with a 95% confidence interval of 0.229 to 0.443. Publication-bias adjustment gave a smaller estimate; varied delivery and study quality limit certainty. There is no universal proven session length.","This course combines a future scene with your existing direction and a concrete act. That package has not been tested. Treat a missing resource, care duty, or unsafe setting as a real constraint, not an internal weakness. A practical response might be a smaller relevant artifact, a request for help, or a different opportunity. Record the actual artifact or interaction separately from the scene. If imagining the future adds pressure or distress, leave it out and continue with a directly chosen act."]}],sourceIds:["meaning-carrillo","meaning-best-possible-self","meaning-mental-contrasting"]}},{schemaVersion:2,revision:2,id:"meaning-6",courseId:"meaning",locale:"en",title:"Another missed plan? Keep what worked",goal:"Use your records to repeat, adapt, or stop one values-linked experiment next week.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Another missed plan? Use your actual attempts to choose what comes next.",reason:{id:"meaning-6-reason",label:"Which act earned another place in your real week?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep a useful small act","Change the cue that failed","Protect a sustainable direction"]},why:{id:"meaning-6-why",label:"Which act earned another place in your real week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Planning an act and doing it are different. Research supports cue-linked plans and progress monitoring for goal attainment on average. Neither establishes that a daily act increases meaning. Keep your experiment’s facts separate from the feeling it gave you.","Look back at the same direction and your actual records. Which opening happened? Which minimum served its purpose? Choose one thing to repeat or change next week. Keep the useful act; drop extra rituals. A missed opportunity is information, not a habit deadline or a verdict on your values. Support, rest, and stopping a harmful plan remain options."],example:{title:"Tomás plans from his records",text:"On Sunday at the kitchen table, Tomás sees two conversations, one unavailable opening, and an unanswered help request in his records. Two minutes after dinner worked better than a late evening slot. He asks his daughter about the model again and listens. For next week he keeps that cue, with another support request if visits crowd it out."}},move:{invitation:"Use your records. Keep one useful act for the next week.",instructions:["Compare the actual openings and minimums you tried.","Change one condition, then make the next attempt."],prompts:[],suggestions:{action:["Repeat my useful listening act","Repeat my useful project contribution","Make the support request my records suggest"],minimum:["Listen to one answer","Produce one usable sentence","Send one specific support request"],cue:["When we sit down after dinner","At my tested project cue","Before the next care arrangement"],place:["At the kitchen table","At my usual work surface","In a safe message thread"],minutes:[2,5],fallback:["Use my tested smaller version","Choose another realistic opening","Get support or pause this plan"],observation:["The act and whether the cue happened","What my changed condition allowed","Whether the minimum still served my direction"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Repeat my useful listening act",minimum:"Listen to one answer",minutes:2,cueHint:"When we sit down after dinner",placeHint:"At the kitchen table",obstacleHint:"The old slot no longer fits my responsibilities.",fallbackHint:"Use my tested smaller version",observationHint:"The act and whether the cue happened"},stopRule:"Change or stop plans that conflict with safety, care, or needed recovery.",accessibleAlternative:"Keep one accessible act, ask for support, or choose rest without adding a new ritual."},result:{question:"Did you do the next minimum?",observationPrompt:"What did you actually do, and did the chosen cue occur?"},judgment:{primary:{id:"meaning-6-tested-opening-decision",scenario:"Tomás’s late-night slot failed twice because visits ran late. Dinner supported two brief conversations. Weekend availability is uncertain. He wants contact next week and can use the dinner opening again.",question:"Which next-week plan best uses these records?",options:[{id:"meaning-6-earlier-night",text:"Move the evening conversation thirty minutes earlier, aiming to keep a longer uninterrupted discussion.",feedback:"An earlier slot could preserve a longer conversation. The records still show visits running late, and do not establish that this shift avoids them. Test the dinner opening that already supported contact."},{id:"meaning-6-weekend-conversation",text:"Reserve a longer weekend conversation so weekday visits no longer compete with the planned contact.",feedback:"A weekend conversation may be valuable if they agree a slot. Availability is uncertain here. Keep the tested dinner minimum for next week and arrange a longer conversation when a real opening exists."},{id:"tested-cue",text:"Keep connection, use the dinner minimum, and record the next attempt before changing anything else.",feedback:"This repeats an opening that supported the chosen act. It does not guarantee another conversation. Record whether the cue occurred and what happened, then decide whether more support or a change is needed."}],bestOptionId:"tested-cue"}},carry:{takeaway:"Keep one direction, one useful act, and a record that improves the next attempt.",followUp:{questionId:"meaning-6-return",question:"Did the condition chosen from your records help the next act?",observationPrompt:"Did the cue occur, and what did that condition enable?",adjustmentPrompt:"Repeat the condition, change it, get support, or stop?"}},goDeeper:{sections:[{heading:"Planning and monitoring answer behavioral questions",paragraphs:["Gollwitzer and Sheeran pooled 94 independent tests with 8,461 participants [M11]. Specific situation-response plans improved goal attainment on average, across varied designs and settings. Harkin and colleagues reviewed 138 randomized monitoring studies [M14]. Their pooled goal-attainment estimate was d = 0.40, with a 95% confidence interval of 0.32 to 0.48. Small-study asymmetry was detected, and a sensitivity analysis estimated d = 0.19. These results concern goal attainment, not a promise of fulfillment.","ODA’s receipt and next-day return have not been validated by these reviews. Their purpose is to compare a particular commitment with a factual attempt, then choose a better fit. Public tracking is unnecessary. Keep sensitive details off ODA if you prefer. A future plan stays planned, and an absent report stays unknown. You can repeat an effective minimum without increasing its size. A practical support request or rest plan may serve the same direction more appropriately than another demanding performance."]},{heading:"A habit estimate is not a deadline",paragraphs:["Lally and colleagues followed 96 participants in an 84-day observational study [M15]. Participants chose eating, drinking, or activity behaviors with daily cues. Modeled automaticity grew at widely differing rates. The familiar 66-day median and 18–254-day range describe fitted estimates, with longer estimates extending beyond observation. They are not deadlines for your action, evidence that values become automatic, or proof that several missed days have no effect. A single missed opportunity had little measured impact in that study.","Your experiment uses a nonfood, values-linked act and a next-day review. That is an adaptation, not the study protocol. Consolidate what your records support: a workable cue, a useful minimum, and a response to the actual obstacle. Leave out an exercise that did not help. Do not repair an interrupted week by doubling every demand. Choose the next feasible opportunity, ask for support when needed, and keep the historical record intact when you change the plan."]}],sourceIds:["meaning-planning","meaning-monitoring","meaning-habits"]}}],c=[{id:"meaning-1",practice:["Choose one contribution or connection; hardship reflection is optional.","Name a useful act and a safe opening.","Do the chosen act and record what happened."],correct:1,photo:{id:"1469474968028-56623f02e42e",alt:"A lone figure on a rock above a misty valley"}},{id:"meaning-2",practice:["Reuse your chosen direction and act.","Protect a feasible slot by naming one nonurgent trade-off.","Do the useful minimum and record what waited."],correct:2,photo:{id:"1470071459604-3b5ec3a7fe05",alt:"Clouds drifting over green cliffs and a valley"}},{id:"meaning-3",practice:["Name a reason you endorse while allowing mixed motives.","Protect necessary obligations and choose one reversible elective trade-off.","Carry out the act and record the choice without grading guilt."],correct:0,photo:{id:"1447752875215-b2761acb3c5d",alt:"A wooden footbridge through a green forest"}},{id:"meaning-4",practice:["Check what practical help or protection is possible.","Choose a specific request, safe boundary, or needed rest.","Carry out the chosen move without requiring meaning or a silver lining."],correct:2,photo:{id:"1519681393784-d120267933ba",alt:"Stars above snowy mountains at night"}},{id:"meaning-5",practice:["Optionally picture a modest near-future scene; this is preparation, not the original writing protocol.","Name one real obstacle and a feasible response.","Do one relevant piece and record it separately from the scene."],correct:1,photo:{id:"1501785888041-af3ef285b470",alt:"A calm lake surrounded by mountains"}},{id:"meaning-6",practice:["Compare the actual attempts for your existing direction.","Choose one condition to repeat or change next week.","Try the useful minimum and record the cue and act."],correct:1,photo:{id:"1472214103451-9374bd1c798e",alt:"A green meadow with trees in soft light"}}],d={id:"meaning",title:"Busy but directionless? Give what matters a turn",subtitle:"6 lessons to turn one valued direction into real acts, honest records, and a workable next week.",description:"Choose one contribution or relationship worth attending to. Test a small action, face its trade-offs, and adjust from what actually happens.",scope:"For adults who feel busy but directionless, are at a crossroads, or want their days to reflect what they care about. It is education and self-reflection, not therapy or treatment. If emptiness or hopelessness persists or daily functioning becomes difficult, talk to a doctor or mental health professional. You can seek support sooner. For thoughts of suicide or an emotional crisis in the US, call or text 988; elsewhere use local crisis support. For immediate danger, use local emergency services.",outcome:"One values-linked experiment with actual attempt records and a next-week plan that respects your responsibilities.",photo:{id:"1500530855697-b586d89ba3ee",alt:"A road winding through open hills toward the horizon"},lessons:r.map((e,s)=>{const a=c[s],t=e.judgment.primary,i=t.options.find(n=>n.id===t.bestOptionId),o=t.options.filter(n=>n.id!==t.bestOptionId).map(n=>n.text);return o.splice(a.correct,0,i.text),{...a,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,reflection:e.direction.reason.label,question:`${t.scenario} ${t.question}`,options:o,feedback:i.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds}})};export{d as COURSE,r as MEANING_LESSONS_V2,l as SOURCES};
